import heapq
from bisect import bisect_left
from collections import defaultdict

def earliest_arrival(connections, transfer, source, target, start_time, max_boardings):
    if source == target:
        return start_time
    if max_boardings <= 0 or not connections:
        return None

    num_stations = len(transfer)

    # Group connections by trip_id
    trips_dict = defaultdict(list)
    for c in connections:
        if c[3] >= start_time:  # Cannot use connections departing before start_time
            trips_dict[c[0]].append(c)

    if not trips_dict:
        return None

    trips = []
    station_deps = [[] for _ in range(num_stations)]

    # Build sorted chains for each trip and collect departures per station
    for t_idx, (_, c_list) in enumerate(trips_dict.items()):
        c_list.sort(key=lambda x: x[3])
        chain = [(c[1], c[2], c[3], c[4]) for c in c_list]
        trips.append(chain)
        for pos, (u, v, dep, arr) in enumerate(chain):
            station_deps[u].append((dep, t_idx, pos))

    # Sort departures at each station by departure time
    for u in range(num_stations):
        if station_deps[u]:
            station_deps[u].sort(key=lambda x: x[0])

    INF = float('inf')

    # Choose strategy based on max_boardings.
    # For small max_boardings, round-based DP (RAPTOR-style) avoids heap overhead.
    # For large max_boardings, Dijkstra processes each connection at most once.
    if max_boardings <= 200:
        ready = [INF] * num_stations
        ready[source] = start_time
        best_target = INF

        # Pointers to the end of unvisited departures for each station
        dep_ptr = [len(station_deps[u]) for u in range(num_stations)]
        # Earliest position reached in each trip
        trip_Limit = [len(chain) for chain in trips]

        changed_stations = [source]
         rounds = min(max_boardings, len(connections))

        for _ in range(rounds):
            if not changed_stations:
                break

            boarded_trips = {}
            for u in changed_stations:
                r_time = ready[u]
                if r_time >= best_target:
                    continue
                deps = station_deps[u]
                ptr = dep_ptr[u]
                # Scan backwards to board all newly reachable departures at u
                while ptr > 0 and deps[ptr - 1][0] >= r_time:
                    ptr -= 1
                    _, t_idx, pos = deps[ptr]
                    if pos < trip_Limit[t_idx]:
                        if t_idx not in boarded_trips or pos < boarded_trips[t_idx]:
                            boarded_trips[t_idx] = pos
                dep_ptr[u] = ptr

            if not boarded_trips:
                break

            next_ready_updates = {}
            for t_idx, start_pos in boarded_trips.items():
                end_pos = trip_Limit[t_idx]
                chain = trips[t_idx]
                for pos in range(start_pos, end_pos):
                    _, v, _, arr = chain[pos]
                    if v == target and arr < best_target:
                        best_target = arr
                    nr = arr + transfer[v]
                    if nr < ready[v]:
                        if v not in next_ready_updates or nr < next_ready_updates[v]:
                            next_ready_updates[v] = nr
                trip_Limit[t_idx] = start_pos

            changed_stations = []
            for v, nr in next_ready_updates.items():
                if nr < ready[v]:
                    ready[v] = nr
                    changed_stations.append(v)

        return best_target if best_target != INF else None

    else:
        # Dijkstra-like approach for large max_boardings
        dep_times = [[x[0] for x in station_deps[u]] for u in range(num_stations)]
        next_ptr = [len(station_deps[u]) for u in range(num_stations)]
        min_b_station = [INF] * num_stations
        min_b_conn = [[INF] * len(chain) for chain in trips]

        # Priority queue stores tuples of: (time, event_type, b, id1, id2)
        # event_type 0: ALIGHT / ARRIVAL at station (id1 = station)
        # event_type 1: READY at station (id1 = station)
        # event_type 2: RIDE connection (id1 = t_idx, id2 = pos)
        pq = []

        min_b_station[source] = 0
        heapq.heappush(pq, (start_time, 1, 0, source, 0))

        while pq:
            time, ev_type, b, id1, id2 = heapq.heappop(pq)

            if ev_type == 0:
                if id1 == target:
                    return time

            elif ev_type == 1:
                u = id1
                if b > min_b_station[u] or b >= max_boardings:
                    continue
                deps = station_deps[u]
                idx = bisect_left(dep_times[u], time)
                limit = next_ptr[u]
                if idx < limit:
                    nb = b + 1
                    for i in range(idx, limit):
                        dep, t_idx, pos = deps[i]
                        if nb < min_b_conn[t_idx][pos]:
                            min_b_conn[t_idx][pos] = nb
                            heapq.heappush(pq, (dep, 2, nb, t_idx, pos))
                    next_ptr[u] = idx

            elif ev_type == 2:
                t_idx, pos = id1, id2
                if b > min_b_conn[t_idx][pos]:
                    continue
                chain = trips[t_idx]
                _, v, _, arr = chain[pos]

                if v == target:
                    heapq.heappush(pq, (arr, 0, b, v, 0))

                if b < min_b_station[v]:
                    min_b_station[v] = b
                    if b < max_boardings:
                        heapq.heappush(pq, (arr + transfer[v], 1, b, v, 0))

                if pos + 1 < len(chain):
                    if b < min_b_conn[t_idx][pos + 1]:
                        min_b_conn[t_idx][pos + 1] = b
                        next_dep = chain[pos + 1][2]
                        heapq.heappush(pq, (next_dep, 2, b, t_idx, pos + 1))

        return None

def run_lock_manager(ops):
    log = []

    # Transaction states: 0 = ACTIVE, 1 = WAITING, 2 = FINISHED
    tx_state = {}
    # tx -> dict of (res -> mode)
    tx_locks = {}
    # tx -> (res, mode, is_upgrade) if currently WAITING
    tx_wait = {}

    # Resource state:
    # res -> dict of (tx -> mode) for current holders
    res_holders = {}
    # res -> list of [tx, mode, is_upgrade]
    # All upgrade requests are kept at the front: indices [0 .. num_upgrades - 1]
    res_queue = {}
    res_num_upgrades = {}

    def is_compatible_for_queue(holders, tx, mode):
        """Check if mode is compatible with all current holders of R other than tx."""
        if mode == "S":
            for h_tx, h_mode in holders.items():
                if h_tx != tx and h_mode == "X":
                    return False
            return True
        else:  # mode == "X"
            for h_tx in holders:
                if h_tx != tx:
                    return False
            return True

    def process_queue(res, op_idx):
        queue = res_queue.get(res)
        if not queue:
            return
        holders = res_holders[res]
        while queue:
            u_tx, mode, is_upg = queue[0]
            if is_compatible_for_queue(holders, u_tx, mode):
                queue.pop(0)
                if is_upg:
                    res_num_upgrades[res] -= 1
                holders[u_tx] = mode
                tx_locks[u_tx][res] = mode
                tx_state[u_tx] = 0  # ACTIVE
                del tx_wait[u_tx]
                log.append(("GRANT", op_idx, u_tx, res, mode))
            else:
                break

    def release(tx, op_idx):
        affected = set()
        if tx in tx_wait:
            w_res, w_mode, w_upg = tx_wait.pop(tx)
            affected.add(w_res)
            q = res_queue[w_res]
            for idx, item in enumerate(q):
                if item[0] == tx:
                    q.pop(idx)
                    if w_upg:
                        res_num_upgrades[w_res] -= 1
                    break

        if tx in tx_locks:
            for l_res in tx_locks[tx]:
                affected.add(l_res)
                del res_holders[l_res][tx]
            tx_locks[tx].clear()

        for res in sorted(affected):
            process_queue(res, op_idx)

    def find_cycle_victim(start_nodes):
        """
        Finds the maximum transaction ID among all transactions that lie on at least
        one cycle in the wait-for graph reachable from `start_nodes`.
        """
        index = 0
        indices = {}
        lowlink = {}
        stack = []
        on_stack = set()
        max_victim = -1

        # Per-resource watermarks to avoid O(|Q|^2) edge traversals
        res_x_done = set()
        res_s_done = set()
        res_q_Watermark = {}

        # Iterative Tarjan's DFS stack: [node, neighbor_list, neighbor_idx]
        dfs_stack = []

        def get_neighbors(u):
            if tx_state.get(u) != 1:
                return []
            res, mode, _ = tx_wait[u]
            neighbors = []
            holders = res_holders[res]

            # 1. Holders of R incompatible with u's request
            if mode == "S":
                if res not in res_x_done:
                    res_x_done.add(res)
                    for h_tx, h_mode in holders.items():
                        if h_tx != u and h_mode == "X":
                            neighbors.append(h_tx)
                else:
                    # Still need direct back-edges/cross-edges to already visited holders
                    # Actually, if res_x_done is set, an earlier node in this DFS already
                    # bears all X-holder edges, and u also reaches that earlier node (or shares
                    # the same holders). To be completely exact for Tarjan's SCC, we include
                    # holders directly, as there is at most 1 X-holder anyway, or for X mode,
                    # only when not yet exhausted, wait:
                    for h_tx, h_mode in holders.items():
                        if h_tx != u and h_mode == "X":
                            neighbors.append(h_tx)
            else:  # mode == "X"
                for h_tx in holders:
                    if h_tx != u:
                        neighbors.append(h_tx)

            # 2. Queued requests on R ahead of u
            q = res_queue[res]
            # Find u's position or scan up to u
            # Since u waits for everything ahead of it, and if v is immediately ahead of u
            # (or at the watermark), v waits for everything ahead of v!
            # Plus, v ALSO waits for all holders if v's mode is X (or X-holders if v's mode is S).
            # Thus, simply adding the segment from watermark to u's position (inclusive of watermark)
            # preserves exact reachability and SCCs!
            wm = res_q_Watermark.get(res, 0)
            u_pos = -1
            for i in range(wm, len(q)):
                if q[i][0] == u:
                    u_pos = i
                    break
            if u_pos != -1:
                # Include watermark item (if > 0, watermark-1 was already processed and reaches everything before it)
                start_i = max(0, wm - 1)
                for i in range(start_i, u_pos):
                    neighbors.append(q[i][0])
                res_q_Watermark[res] = u_pos + 1
            else:
                # u is before the current watermark; just link to u's immediate predecessor if any,
                # and all items up to u (since u is earlier than wm, we already scanned past u,
                # so u was already discovered or we just link to u-1)
                for i, item in enumerate(q):
                    if item[0] == u:
                        u_pos = i
                        break
                if u_pos > 0:
                    neighbors.append(q[u_pos - 1][0])
                    # Also link to index 0 if upgrades vs non-upgrades have different holder edges
                    for i in range(u_pos - 1):
                        neighbors.append(q[i][0])

            return neighbors

        for start_node in start_nodes:
            if start_node in indices or tx_state.get(start_node) != 1:
                continue

            indices[start_node] = lowlink[start_node] = index
            index += 1
            stack.append(start_node)
            on_stack.add(start_node)
            dfs_stack.append([start_node, get_neighbors(start_node), 0])

            while dfs_stack:
                 frame = dfs_stack[-1]
                 u, nbrs, idx = frame
                 if idx < len(nbrs):
                     v = nbrs[idx]
                     frame[2] += 1
                     if v not in indices:
                         indices[v] = lowlink[v] = index
                         index += 1
                         stack.append(v)
                         on_stack.add(v)
                         dfs_stack.append([v, get_neighbors(v), 0])
                     elif v in on_stack:
                         if indices[v] < lowlink[u]:
                             lowlink[u] = indices[v]
                 else:
                     dfs_stack.pop()
                     if dfs_stack:
                         parent = dfs_stack[-1][0]
                         if lowlink[u] < lowlink[parent]:
                             lowlink[parent] = lowlink[u]

                     if lowlink[u] == indices[u]:
                         scc = []
                         while True:
                             w = stack.pop()
                             on_stack.remove(w)
                             scc.append(w)
                             if w == u:
                                 break
                         if len(scc) > 1:
                             for w in scc:
                                 if w > max_victim:
                                     max_victim = w

        return max_victim

    for op_idx, op in enumerate(ops):
        kind = op[0]
        tx = op[1]

        if tx not in tx_state:
            tx_state[tx] = 0
            tx_locks[tx] = {}

        state = tx_state[tx]
        if state == 1 or state == 2:
            log.append(("IGNORED", op_idx, tx))
            continue

        if kind == "COMMIT":
            log.append(("COMMIT", op_idx, tx))
            release(tx, op_idx)
            tx_state[tx] = 2
            continue

        # Lock request ("S" or "X")
        mode = kind
        res = op[2]

        if res not in res_holders:
            res_holders[res] = {}
            res_queue[res] = []
            res_num_upgrades[res] = 0

        holders = res_holders[res]
        queue = res_queue[res]
        held_mode = holders.get(tx)

        # 3a. Already holds sufficient lock
        if held_mode == "X" or (held_mode == "S" and mode == "S"):
            log.append(("HELD", op_idx, tx, res))
            continue

        # 3b. Upgrade request (holds S, requests X)
        if held_mode == "S" and mode == "X":
            if len(holders) == 1:
                holders[tx] = "X"
                tx_locks[tx][res] = "X"
                log.append(("GRANT", op_idx, tx, res, "X"))
            else:
                ins_pos = res_num_upgrades[res]
                queue.insert(ins_pos, [tx, "X", True])
                res_num_upgrades[res] += 1
                tx_state[tx] = 1
                tx_wait[tx] = (res, "X", True)
                log.append(("WAIT", op_idx, tx, res, "X"))

                # Deadlock detection starting from newly waiting transaction
                victim = find_cycle_victim([tx])
                while victim != -1:
                    log.append(("ABORT", op_idx, victim))
                    release(victim, op_idx)
                    tx_state[victim] = 2
                    # Re-check all remaining waiting transactions in case other cycles remain
                    victim = find_cycle_victim([t for t, s in tx_state.items() if s == 1])
            continue

        # 3c. Holds nothing on R
        if not queue and is_compatible_for_queue(holders, tx, mode):
            holders[tx] = mode
            tx_locks[tx][res] = mode
            log.append(("GRANT", op_idx, tx, res, mode))
        else:
            queue.append([tx, mode, False])
            tx_state[tx] = 1
            tx_wait[tx] = (res, mode, False)
            log.append(("WAIT", op_idx, tx, res, mode))

            # Deadlock detection starting from newly waiting transaction
            victim = find_cycle_victim([tx])
            while victim != -1:
                log.append(("ABORT", op_idx, victim))
                release(victim, op_idx)
                tx_state[victim] = 2
                victim = find_cycle_victim([t for t, s in tx_state.items() if s == 1])

    return log

def simulate_vending(prices, stock, bank, events, timeout):
    # Validate event timestamps are non-decreasing before doing anything else
    prev_t = -1
    for t, _, _ in events:
        if t < prev_t:
            raise ValueError("Event times must be non-decreasing")
        prev_t = t

    # Copy mutable state to avoid mutating inputs
    curr_stock = dict(stock)
    curr_bank = {d: bank.get(d, 0) for d in (5, 10, 25, 100)}

    escrow = []
    escrow_total = 0
    last_activity = None
    log = []

    accepted_coins = {5, 10, 25, 100}
    denoms_desc = (100, 25, 10, 5)

    for t, kind, arg in events:
        # 1. Check for pending automatic return BEFORE processing the current event
        if escrow and last_activity is not None and t >= last_activity + timeout:
            coins = tuple(sorted(escrow, reverse=True))
            log.append(("TIMEOUT", last_activity + timeout, coins))
            escrow.clear()
            escrow_total = 0

        # 2. Process the event
        if kind == "coin":
            v = arg
            if v not in accepted_coins or len(escrow) >= 10:
                log.append(("REJECT", t, v))
                # A rejected coin is NOT an activity
            else:
                escrow.append(v)
                escrow_total += v
                last_activity = t

        elif kind == "select":
            s = arg
            last_activity = t  # Any select is an activity

            if s not in prices:
                log.append(("UNKNOWN", t, s))
            elif curr_stock[s] == 0:
                log.append(("SOLD_OUT", t, s))
            elif escrow_total < prices[s]:
                log.append(("NEED", t, prices[s] - escrow_total))
            else:
                # Attempt sale: temporarily move escrow into bank
                for c in escrow:
                    curr_bank[c] += 1

                rem = escrow_total - prices[s]
                change_coins = []

                # Greedy change calculation
                for d in denoms_desc:
                    if rem == 0:
                        break
                    k = min(curr_bank[d], rem // d)
                    if k > 0:
                        curr_bank[d] -= k
                        rem -= k * d
                        change_coins.extend([d] * k)

                if rem == 0:
                    # Sale succeeds
                    curr_stock[s] -= 1
                    escrow.clear()
                    escrow_total = 0
                    log.append(("VEND", t, s, tuple(change_coins)))
                else:
                    # Rollback bank changes and keep escrow intact
                    for c in change_coins:
                        curr_bank[c] += 1
                    for c in escrow:
                        curr_bank[c] -= 1
                    log.append(("EXACT_ONLY", t, s))

        elif kind == "cancel":
            last_activity = t  # Any cancel is an activity
            if escrow:
                coins = tuple(sorted(escrow, reverse=True))
                log.append(("RETURN", t, coins))
                escrow.clear()
                escrow_total = 0

    # Perform any still-pending automatic return after the last event
    if escrow and last_activity is not None:
        coins = tuple(sorted(escrow, reverse=True))
        log.append(("TIMEOUT", last_activity + timeout, coins))
        escrow.clear()
        escrow_total = 0

    final_bank = (curr_bank[5], curr_bank[10], curr_bank[25], curr_bank[100])
    return log, final_bank

import re

# Precompiled regular expressions for validation
_NAME_RE = re.compile(r"^[a-z0-9_]+\Z")
_PRINCIPAL_RE = re.compile(r"^(\*|(user|group):[a-z0-9_]+)\Z")
_ACTION_WORD_RE = re.compile(r"^[a-z]+\Z")
_ACTION_LIST_RE = re.compile(r"^(\*|[a-z]+(,[a-z]+)*)\Z")
_RES_SEG_RE = re.compile(r"^(\*|\*\*|[a-z0-9._-]+)\Z")
_PATH_SEG_RE = re.compile(r"^[a-z0-9._-]+\Z")


def _match_segments(res_segs: tuple[str, ...], path_segs: tuple[str, ...]) -> bool:
    """
    Matches resource pattern segments against path segments in linear/polynomial time
    (mirrors standard wildcard string matching with '*' and '?').
    """
    p_idx = 0
    r_idx = 0
    p_len = len(path_segs)
    r_len = len(res_segs)
    star_idx = -1
    match_idx = 0

    while p_idx < p_len:
        if r_idx < r_len and (res_segs[r_idx] == "*" or res_segs[r_idx] == path_segs[p_idx]):
            r_idx += 1
            p_idx += 1
        elif r_idx < r_len and res_segs[r_idx] == "**":
            star_idx = r_idx
            match_idx = p_idx
            r_idx += 1
        elif star_idx != -1:
            r_idx = star_idx + 1
            match_idx += 1
            p_idx = match_idx
        else:
            return False

    while r_idx < r_len and res_segs[r_idx] == "**":
        r_idx += 1

    return r_idx == r_len


def evaluate_access(rules: list[str], requests: list[tuple]) -> list[str]:
    # 1. Validate top-level container types
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    # 2. Validate and parse rules
    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")

        effect, principal, action, resource = fields

        # Validate EFFECT
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        # Validate PRINCIPAL
        if not _PRINCIPAL_RE.match(principal):
            raise ValueError(f"rule {i}: bad principal {principal!r}")

        # Validate ACTION
        if not _ACTION_LIST_RE.match(action):
            raise ValueError(f"rule {i}: bad action {action!r}")

        # Validate RESOURCE
        if not resource.startswith("/"):
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        if resource == "/":
            raw_res_segs = []
        else:
            raw_res_segs = resource[1:].split("/")
            if not all(_RES_SEG_RE.match(seg) for seg in raw_res_segs):
                raise ValueError(f"rule {i}: bad resource {resource!r}")

        # Calculate specificity & prepare internal representations for fast evaluation
        L = sum(1 for seg in raw_res_segs if seg not in ("*", "**"))

        if principal == "*":
            P = 0
            p_type, p_val = "*", None
        elif principal.startswith("user:"):
            P = 2
            p_type, p_val = "user", principal[5:]
        else:
            P = 1
            p_type, p_val = "group", principal[6:]

        if action == "*":
            A = 0
            actions_set = None
        else:
            A = 1
            actions_set = frozenset(action.split(","))

        # Collapse consecutive '**' segments into a single '**' for faster matching
        collapsed_segs = []
        for seg in raw_res_segs:
            if seg == "**" and collapsed_segs and collapsed_segs[-1] == "**":
                continue
            collapsed_segs.append(seg)
        res_segs = tuple(collapsed_segs)

        has_double_star = "**" in res_segs
        min_len = len(res_segs) - res_segs.count("**")

        # Ranking tuple: higher tuple value wins.
        # Specificity (L, P, A) > DENY over ALLOW (is_deny) > smaller rule index (-i)
        is_deny = 1 if effect == "DENY" else 0
        rank = (L, P, A, is_deny, -i)
        decision_str = f"{effect} by rule {i}"

        parsed_rules.append((
            rank, p_type, p_val, actions_set, res_segs, has_double_star, min_len, decision_str
        ))

    # 3. Validate and parse requests
    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")

        user, groups, action, path = req

        if not isinstance(user, str) or not _NAME_RE.match(user):
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list) or not all(
            isinstance(g, str) and _NAME_RE.match(g) for g in groups
        ):
            raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or not _ACTION_WORD_RE.match(action):
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError(f"request {j}: bad path {path!r}")

        if path == "/":
            path_segs = ()
        else:
            raw_path_segs = path[1:].split("/")
            if not all(_PATH_SEG_RE.match(seg) for seg in raw_path_segs):
                raise ValueError(f"request {j}: bad path {path!r}")
            path_segs = tuple(raw_path_segs)

        parsed_requests.append((user, frozenset(groups), action, path_segs))

    # 4. Sort rules by descending rank so the first matching rule is the optimal one
    parsed_rules.sort(key=lambda r: r[0], reverse=True)

    # 5. Evaluate requests
    decisions = []
    for user, groups_set, req_action, path_segs in parsed_requests:
        path_len = len(path_segs)
        decision = "DENY by default"

        for (
            rank, p_type, p_val, actions_set, res_segs, has_double_star, min_len, decision_str
        ) in parsed_rules:
            # Fast length check before anything else
            if has_double_star:
                if path_len < min_len:
                    continue
            else:
                if path_len != min_len:
                    continue

            # Principal check
            if p_type == "user":
                if p_val != user:
                    continue
            elif p_type == "group":
                if p_val not in groups_set:
                    continue

            # Action check
            if actions_set is not None and req_action not in actions_set:
                continue

            # Resource segment check
            if _match_segments(res_segs, path_segs):
                decision = decision_str
                break

        decisions.append(decision)

    return decisions

import copy
import json
import re

_IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$", re.ASCII)


def _get_type(v) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "bool"
    if isinstance(v, int):
        return "int"
    if isinstance(v, float):
        return "float"
    if isinstance(v, str):
        return "str"
    if isinstance(v, list):
        return "list"
    if isinstance(v, dict):
        return "dict"
    return type(v).__name__


def _make_path(parent: str, name: str) -> str:
    if _IDENT_RE.match(name):
        return f"{parent}.{name}"
    return f"{parent}[{json.dumps(name, ensure_ascii=False)}]"


def merge_layers(layers) -> tuple[dict, list[str]]:
    if not isinstance(layers, list):
        raise TypeError("layers must be a list")

    result = {}
    warnings = []

    def _merge(target: dict, overlay: dict, path: str, layer_idx: int) -> None:
        for k, v in overlay.items():
            if not isinstance(k, str):
                raise TypeError(f"layer {layer_idx}: non-string key at {path}")

            if k.startswith("-"):
                directive = "DELETE"
                name = k[1:]
            elif k.endswith("+"):
                directive = "APPEND"
                name = k[:-1]
            else:
                directive = "SET"
                name = k

            if name == "":
                raise ValueError(f"layer {layer_idx}: empty key name at {path}")

            q = _make_path(path, name)

            if directive == "DELETE":
                if v is not None:
                    raise ValueError(f"layer {layer_idx}: delete directive needs null at {q}")
                if name in target:
                    del target[name]
                else:
                    warnings.append(f"layer {layer_idx}: delete of missing key at {q}")

            elif directive == "APPEND":
                if not isinstance(v, list):
                    raise ValueError(f"layer {layer_idx}: append directive needs a list at {q}")
                if name not in target:
                    target[name] = copy.deepcopy(v)
                elif isinstance(target[name], list):
                    target[name].extend(copy.deepcopy(v))
                else:
                    t_type = _get_type(target[name])
                    raise ValueError(f"layer {layer_idx}: cannot append to {t_type} at {q}")

            else:  # SET
                if name in target:
                    old_type = _get_type(target[name])
                    new_type = _get_type(v)
                    if old_type != new_type:
                        warnings.append(
                            f"layer {layer_idx}: type change at {q}: {old_type} -> {new_type}"
                        )

                if isinstance(v, dict):
                    if name in target and isinstance(target[name], dict):
                        _merge(target[name], v, q, layer_idx)
                    else:
                        target[name] = {}
                        _merge(target[name], v, q, layer_idx)
                else:
                    target[name] = copy.deepcopy(v)

    for idx, layer in enumerate(layers):
        if not isinstance(layer, dict):
            raise TypeError(f"layer {idx} is not a dict")
        _merge(result, layer, "$", idx)

    return result, warnings

import re
from datetime import date as dt_date

_OPENING_RE = re.compile(r"-?(0|[1-9][0-9]{0,8})\.[0-9]{2}")
_DATE_RE = re.compile(r"(19[0-9]{2}|2[0-9]{3})-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?")


def _parse_cents(s: str) -> int:
    neg = s.startswith("-")
    if neg:
        s = s[1:]
    if "." in s:
        whole, frac = s.split(".")
        frac = (frac + "00")[:2]
    else:
        whole, frac = s, "00"
    cents = int(whole) * 100 + int(frac)
    return -cents if neg else cents


def _format_money(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    dollars, rem = divmod(cents, 100)
    return f"{sign}{dollars:,}.{rem:02d}"


def _format_memo(memo: str) -> str:
    norm = " ".join(memo.split())
    if len(norm) > 20:
        norm = norm[:19] + "~"
    return norm.ljust(20)


def render_statement(opening, entries) -> list[str]:
    # 1. Validate opening type
    if not isinstance(opening, str):
        raise TypeError("opening must be a str")

    # 2. Validate opening pattern
    if not _OPENING_RE.fullmatch(opening):
        raise ValueError("opening: bad amount " + repr(opening))

    # 3. Validate entries type
    if not isinstance(entries, list):
        raise TypeError("entries must be a list")

    # 4. Validate each entry
    prev_date = None
    parsed_entries = []

    for i, entry in enumerate(entries):
        # 4a. 4-tuple check
        if not isinstance(entry, tuple) or len(entry) != 4:
            raise TypeError(f"entry {i}: expected 4-tuple")

        d_str, kind, amount, memo = entry

        # 4b. Date check
        if not isinstance(d_str, str) or not _DATE_RE.fullmatch(d_str):
            raise ValueError(f"entry {i}: bad date {d_str!r}")
        try:
            year, month, day = map(int, d_str.split("-"))
            dt_date(year, month, day)
        except ValueError:
            raise ValueError(f"entry {i}: bad date {d_str!r}") from None

        # 4c. Date order check
        if prev_date is not None and d_str < prev_date:
            raise ValueError(f"entry {i}: date out of order")
        prev_date = d_str

        # 4d. Kind check
        if not isinstance(kind, str) or kind not in ("credit", "debit", "fee"):
            raise ValueError(f"entry {i}: bad kind {kind!r}")

        # 4e. Amount check
        if not isinstance(amount, str) or not _AMOUNT_RE.fullmatch(amount):
            raise ValueError(f"entry {i}: bad amount {amount!r}")
        amt_cents = _parse_cents(amount)
        if amt_cents == 0:
            raise ValueError(f"entry {i}: bad amount {amount!r}")

        # 4f. Memo check
        if not isinstance(memo, str) or not memo.split():
            raise ValueError(f"entry {i}: bad memo")
        if any(ord(ch) < 32 or ord(ch) == 127 for ch in memo):
            raise ValueError(f"entry {i}: bad memo")

        parsed_entries.append((d_str, kind, amt_cents, memo))

    # Processing & Rendering
    balance = _parse_cents(opening)
    lines = [f"Opening balance: {_format_money(balance)}"]

    od_fee_dates = set()
    counts = {"credit": 0, "debit": 0, "fee": 0}

    def apply_and_render(d_str: str, kind: str, amt_cents: int, memo: str):
        nonlocal balance
        if kind == "credit":
            balance += amt_cents
            sign = "+"
        else:
            balance -= amt_cents
            sign = "-"

        counts[kind] += 1

        memo_col = _format_memo(memo)
        amt_col = (sign + _format_money(amt_cents)).rjust(14)
        bal_col = _format_money(balance).rjust(15)
        flag = " OD" if balance < 0 else ""

        lines.append(f"{d_str}  {memo_col}  {amt_col}  {bal_col}{flag}")

    for d_str, kind, amt_cents, memo in parsed_entries:
        apply_and_render(d_str, kind, amt_cents, memo)
        if kind == "debit" and balance < 0 and d_str not in od_fee_dates:
            od_fee_dates.add(d_str)
            apply_and_render(d_str, "fee", 2500, "OVERDRAFT FEE")

    lines.append(f"Closing balance: {_format_money(balance)}")
    lines.append(
        f"Credits: {counts['credit']}  Debits: {counts['debit']}  Fees: {counts['fee']}"
    )

    return lines

import re

# Regex helpers for version parts:
# _INT matches 0 or a positive integer without leading zeros.
# _POS_INT matches a positive integer (>= 1) without leading zeros.
_INT = r"(?:0|[1-9][0-9]*)"
_POS_INT = r"(?:[1-9][0-9]*)"

_VERSION_RE = re.compile(rf"\A({_INT})\.({_INT})\.({_INT})(?:~rc({_POS_INT}))?\Z")
_X_STAR_RE = re.compile(rf"\A({_INT})\.\*\Z")
_XY_STAR_RE = re.compile(rf"\A({_INT})\.({_INT})\.\*\Z")
_AT_XY_RE = re.compile(rf"\A@({_INT})\.({_INT})\Z")


def _parse_version(s: str) -> tuple[int, int, int, int, int] | None:
    """
    Parse a version string into a comparable tuple: (X, Y, Z, is_release, rc_num).
    For a plain release X.Y.Z, is_release=1 and rc_num=0.
    For a release candidate X.Y.Z~rcN, is_release=0 and rc_num=N.
    Returns None if s is not a valid version string.
    """
    if not isinstance(s, str):
        return None
    m = _VERSION_RE.match(s)
    if not m:
        return None
    x, y, z, rc = m.groups()
    if rc is None:
        return (int(x), int(y), int(z), 1, 0)
    else:
        return (int(x), int(y), int(z), 0, int(rc))


def _parse_clause(clause: str):
    """
    Parse a single stripped clause into a predicate function `pred(v_tuple) -> bool`,
    or return None if the clause is invalid.
    """
    if clause == "*":
        return lambda v: True

    m = _X_STAR_RE.match(clause)
    if m:
        target_x = int(m.group(1))
        return lambda v, tx=target_x: v[0] == tx

    m = _XY_STAR_RE.match(clause)
    if m:
        target_x = int(m.group(1))
        target_y = int(m.group(2))
        return lambda v, tx=target_x, ty=target_y: v[0] == tx and v[1] == ty

    m = _AT_XY_RE.match(clause)
    if m:
        target_x = int(m.group(1))
        target_y = int(m.group(2))
        return lambda v, tx=target_x, ty=target_y: v[0] == tx and v[1] >= ty

    # Check comparison operators (order matters: 2-char operators before 1-char)
    for op in ("!=", ">=", "<=", "=", ">", "<"):
        if clause.startswith(op):
            v_str = clause[len(op):]
            target_v = _parse_version(v_str)
            if target_v is None:
                return None
            if op == "=":
                return lambda v, tv=target_v: v == tv
            if op == "!=":
                return lambda v, tv=target_v: v != tv
            if op == ">=":
                return lambda v, tv=target_v: v >= tv
            if op == "<=":
                return lambda v, tv=target_v: v <= tv
            if op == ">":
                return lambda v, tv=target_v: v > tv
            if op == "<":
                return lambda v, tv=target_v: v < tv

    # Bare version V (equivalent to =V)
    target_v = _parse_version(clause)
    if target_v is not None:
        return lambda v, tv=target_v: v == tv

    return None


def pick_version(available, constraint) -> str | None:
    # 1. Validate `available` is a list
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    # 2. Validate each element in `available` in index order
    parsed_available = []
    for i, element in enumerate(available):
        v_tuple = _parse_version(element)
        if v_tuple is None:
            raise ValueError(f"invalid version at index {i}: {element!r}")
        parsed_available.append((v_tuple, element))

    # 3. Validate `constraint` is a str
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    # 4. Validate `constraint` is not empty or only spaces
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # 5. Parse and validate alternatives and clauses left to right
    raw_alternatives = constraint.split("|")
    parsed_alternatives = []

    for a_idx, raw_alt in enumerate(raw_alternatives, start=1):
        alt = raw_alt.strip(" ")
        allows_rc = False
        if alt.startswith("?"):
            allows_rc = True
            alt = alt[1:].strip(" ")

        if alt == "":
            raise ValueError(f"alternative {a_idx} is empty")

        raw_clauses = alt.split(",")
        clause_preds = []
        for c_idx, raw_clause in enumerate(raw_clauses, start=1):
            clause = raw_clause.strip(" ")
            pred = _parse_clause(clause)
            if pred is None:
                raise ValueError(f"alternative {a_idx}, clause {c_idx}: invalid clause {clause!r}")
            clause_preds.append(pred)

        parsed_alternatives.append((allows_rc, clause_preds))

    # Matching phase
    best_version_tuple = None
    best_version_str = None

    for v_tuple, v_str in parsed_available:
        is_rc = (v_tuple[3] == 0)
        satisfies_any = False

        for allows_rc, clause_preds in parsed_alternatives:
            if is_rc and not allows_rc:
                continue
            if all(pred(v_tuple) for pred in clause_preds):
                satisfies_any = True
                break

        if satisfies_any:
            if best_version_tuple is None or v_tuple > best_version_tuple:
                best_version_tuple = v_tuple
                best_version_str = v_str

    return best_version_str

import re

_KEY_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_-]*$")
_INT_RE = re.compile(r"^-?(?:0|[1-9][0-9]*)$")
_ESCAPES = {"\\": "\\", '"': '"', "n": "\n", "t": "\t"}


def _parse_scalar(text: str, line_no: int):
    if text[0] == '"':
        out = []
        n = len(text)
        i = 1
        while i < n:
            ch = text[i]
            if ch == "\\":
                if i + 1 >= n:
                    return ("error", line_no, "bad escape")
                esc = _ESCAPES.get(text[i + 1])
                if esc is None:
                    return ("error", line_no, "bad escape")
                out.append(esc)
                i += 2
            elif ch == '"':
                if i != n - 1:
                    return ("error", line_no, "bad string")
                return ("ok", "".join(out))
            else:
                out.append(ch)
                i += 1
        return ("error", line_no, "bad string")

    if text == "true":
        return ("ok", True)
    if text == "false":
        return ("ok", False)
    if text == "null":
        return ("ok", None)
    if _INT_RE.match(text):
        return ("ok", int(text))
    return ("ok", text)


def parse_outline(text: str) -> tuple:
    lines = text.split("\n")

    # Stack of open blocks: each entry is (indent, kind, container)
    # kind: 0 for list, 1 for mapping
    stack = []
    root = None

    # Pending opener: None, or (indent, parent_kind, parent_container, key_or_index)
    pending_opener = None

    key_match = _KEY_RE.match

    for line_no, line in enumerate(lines, 1):
        rest = line.lstrip(" \t")
        if not rest or rest[0] == "#":
            continue

        indent = len(line) - len(rest)
        lead = line[:indent]

        # 1. Check tab in indentation
        if "\t" in lead:
            return ("error", line_no, "tab in indentation")

        # 2 & 3. Determine line kind (0=ITEM, 1=KEY), opener status, and scalar text
        if rest == "-" or rest.startswith("- "):
            kind = 0
            key = None
            raw_scalar = rest[2:].strip(" ")
            is_opener = not raw_scalar
        else:
            colon_idx = rest.find(":")
            if colon_idx <= 0:
                return ("error", line_no, "invalid entry")
            key = rest[:colon_idx]
            if not key_match(key):
                return ("error", line_no, "invalid entry")
            after = rest[colon_idx + 1 :]
            stripped_after = after.strip(" ")
            if not stripped_after:
                kind = 1
                is_opener = True
                raw_scalar = ""
            else:
                if after[0] != " ":
                    return ("error", line_no, "invalid entry")
                kind = 1
                is_opener = False
                raw_scalar = stripped_after

        # 4. Scalar conversion
        if is_opener:
            val = None
        else:
            res = _parse_scalar(raw_scalar, line_no)
            if res[0] == "error":
                return res
            val = res[1]

        # 5. Structure checks
        if not stack:
            if indent != 0:
                return ("error", line_no, "unexpected indent")
            root = [] if kind == 0 else {}
            stack.append((0, kind, root))
            target_container = root
        elif pending_opener is not None and indent > pending_opener[0]:
            _, p_kind, p_container, p_slot = pending_opener
            new_block = [] if kind == 0 else {}
            p_container[p_slot] = new_block
            stack.append((indent, kind, new_block))
            target_container = new_block
        else:
            top_indent = stack[-1][0]
            if indent > top_indent:
                return ("error", line_no, "unexpected indent")
            while stack[-1][0] > indent:
                stack.pop()
            if stack[-1][0] != indent:
                return ("error", line_no, "inconsistent dedent")

            b_indent, b_kind, target_container = stack[-1]
            if kind != b_kind:
                return ("error", line_no, "mixed block")
            if kind == 1 and key in target_container:
                return ("error", line_no, f"duplicate key '{key}'")

        # Insert value and update pending_opener
        if kind == 0:
            if is_opener:
                pending_opener = (indent, 0, target_container, len(target_container))
            else:
                pending_opener = None
            target_container.append(val)
        else:
            if is_opener:
                pending_opener = (indent, 1, target_container, key)
            else:
                pending_opener = None
            target_container[key] = val

    return ("ok", root)

import re

_TOKEN_RE = re.compile(r'[\[\]]|[^ \t\n\r\[\]]+')
_INT_RE = re.compile(r'-?[0-9]+\Z')

_BUILTINS = {
    "dup": 2, "drop": 3, "swap": 4, "over": 5, "rot": 6,
    "+": 7, "-": 8, "*": 9, "/": 10, "%": 11, "<": 12, "=": 13,
    "if": 14, "times": 15, "while": 16, "call": 17, "dip": 18,
}


def run_pile(src: str, max_steps: int) -> tuple:
    tokens = _TOKEN_RE.findall(src)
    n = len(tokens)
    if n == 0:
        return ("ok", [])

    # 1. Structure check and element compilation (iterative to handle deep nesting)
    open_stack = []
    seq_stack = [[]]
    i = 0
    is_int = _INT_RE.match
    builtins = _BUILTINS

    while i < n:
        tok = tokens[i]
        if tok == "[":
            open_stack.append((0, i, None))
            seq_stack.append([])
            i += 1
        elif tok == "]":
            if not open_stack or open_stack[-1][0] != 0:
                return ("error", i, "unmatched ]")
            _, open_idx, _ = open_stack.pop()
            body = tuple(seq_stack.pop())
            seq_stack[-1].append((1, open_idx, body))
            i += 1
        elif tok == ":":
            if open_stack:
                return ("error", i, "misplaced :")
            if i + 1 >= n:
                return ("error", i, "unclosed :")
            name = tokens[i + 1]
            if (
                name in ("[", "]", ":", ";")
                or is_int(name)
                or name in builtins
            ):
                return ("error", i + 1, "bad name")
            open_stack.append((1, i, name))
            seq_stack.append([])
            i += 2
        elif tok == ";":
            if not open_stack or open_stack[-1][0] != 1:
                return ("error", i, "unmatched ;")
            _, open_idx, name = open_stack.pop()
            body = tuple(seq_stack.pop())
            seq_stack[-1].append((19, open_idx, (name, body)))
            i += 1
        elif is_int(tok):
            seq_stack[-1].append((0, i, int(tok)))
            i += 1
        elif tok in builtins:
            seq_stack[-1].append((builtins[tok], i, None))
            i += 1
        else:
            seq_stack[-1].append((20, i, tok))
            i += 1

    if open_stack:
        kind, earliest_idx, _ = open_stack[0]
        return ("error", earliest_idx, "unclosed [" if kind == 0 else "unclosed :")

    top_seq = tuple(seq_stack[0])
    if not top_seq:
        return ("ok", [])

    # 2. Execution with explicit continuation stack
    # Frame kinds:
    #   (0, seq, pos)              - sequence execution
    #   (1, val)                   - dip restore: push val back
    #   (2, q, rem)                - times loop: run non-empty q rem more times
    #   (3, c, b, while_idx, st)   - while loop: st=0 run c, st=1 check cond & run b
    val_stack = []
    call_stack = [(0, top_seq, 0)]
    env = {}
    steps = 0

    while call_stack:
        frame = call_stack[-1]
        fkind = frame[0]

        if fkind == 0:
            _, seq, pos = frame
            if pos >= len(seq):
                call_stack.pop()
                continue
            call_stack[-1] = (0, seq, pos + 1)

            op, idx, arg = seq[pos]
            steps += 1
            if steps > max_steps:
                return ("error", idx, "step limit exceeded")

            if op == 0 or op == 1:  # INT or Quotation
                val_stack.append(arg)
            elif op == 2:  # dup
                if not val_stack:
                    return ("error", idx, "stack underflow")
                val_stack.append(val_stack[-1])
            elif op == 3:  # drop
                if not val_stack:
                    return ("error", idx, "stack underflow")
                val_stack.pop()
            elif op == 4:  # swap
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                val_stack[-1], val_stack[-2] = val_stack[-2], val_stack[-1]
            elif op == 5:  # over
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                val_stack.append(val_stack[-2])
            elif op == 6:  # rot
                if len(val_stack) < 3:
                    return ("error", idx, "stack underflow")
                a = val_stack[-3]
                val_stack[-3] = val_stack[-2]
                val_stack[-2] = val_stack[-1]
                val_stack[-1] = a
            elif 7 <= op <= 13:  # binary int ops: + - * / % < =
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                b = val_stack[-1]
                a = val_stack[-2]
                if type(a) is not int or type(b) is not int:
                    return ("error", idx, "type error")
                if op == 7:
                    res = a + b
                elif op == 8:
                    res = a - b
                elif op == 9:
                    res = a * b
                elif op == 10:
                    if b == 0:
                        return ("error", idx, "division by zero")
                    res = a // b
                elif op == 11:
                    if b == 0:
                        return ("error", idx, "division by zero")
                    res = a % b
                elif op == 12:
                    res = 1 if a < b else 0
                else:
                    res = 1 if a == b else 0
                val_stack.pop()
                val_stack[-1] = res
            elif op == 14:  # if
                if len(val_stack) < 3:
                    return ("error", idx, "stack underflow")
                f = val_stack[-1]
                t = val_stack[-2]
                c = val_stack[-3]
                if type(c) is not int or type(t) is not tuple or type(f) is not tuple:
                    return ("error", idx, "type error")
                del val_stack[-3:]
                chosen = t if c != 0 else f
                if chosen:
                    call_stack.append((0, chosen, 0))
            elif op == 15:  # times
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                cnt = val_stack[-1]
                q = val_stack[-2]
                if type(q) is not tuple or type(cnt) is not int:
                    return ("error", idx, "type error")
                if cnt < 0:
                    return ("error", idx, "negative count")
                del val_stack[-2:]
                if cnt > 0 and q:
                    call_stack.append((2, q, cnt))
            elif op == 16:  # while
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                b = val_stack[-1]
                c = val_stack[-2]
                if type(c) is not tuple or type(b) is not tuple:
                    return ("error", idx, "type error")
                del val_stack[-2:]
                call_stack.append((3, c, b, idx, 1))
                if c:
                    call_stack.append((0, c, 0))
            elif op == 17:  # call
                if not val_stack:
                    return ("error", idx, "stack underflow")
                q = val_stack[-1]
                if type(q) is not tuple:
                    return ("error", idx, "type error")
                val_stack.pop()
                if q:
                    call_stack.append((0, q, 0))
            elif op == 18:  # dip
                if len(val_stack) < 2:
                    return ("error", idx, "stack underflow")
                q = val_stack[-1]
                if type(q) is not tuple:
                    return ("error", idx, "type error")
                a = val_stack[-2]
                del val_stack[-2:]
                if q:
                    call_stack.append((1, a))
                    call_stack.append((0, q, 0))
                else:
                    val_stack.append(a)
            elif op == 19:  # definition
                env[arg[0]] = arg[1]
            elif op == 20:  # user word
                body = env.get(arg)
                if body is None:
                    return ("error", idx, f"unknown word '{arg}'")
                if body:
                    call_stack.append((0, body, 0))

        elif fkind == 1:  # dip restore
            val_stack.append(frame[1])
            call_stack.pop()

        elif fkind == 2:  # times
            _, q, rem = frame
            if rem <= 1:
                call_stack[-1] = (0, q, 0)
            else:
                call_stack[-1] = (2, q, rem - 1)
                call_stack.append((0, q, 0))

        elif fkind == 3:  # while
            _, c, b, w_idx, state = frame
            if state == 0:
                call_stack[-1] = (3, c, b, w_idx, 1)
                if c:
                    call_stack.append((0, c, 0))
            else:
                if not val_stack:
                    return ("error", w_idx, "stack underflow")
                v = val_stack[-1]
                if type(v) is not int:
                    return ("error", w_idx, "type error")
                val_stack.pop()
                if v != 0:
                    call_stack[-1] = (3, c, b, w_idx, 0)
                    if b:
                        call_stack.append((0, b, 0))
                else:
                    call_stack.pop()

    # 3. Format result stack (iterative to handle deeply nested quotations)
    memo = {}

    def format_quot(root_q):
        if id(root_q) in memo:
            return list(memo[id(root_q)])
        res_root = []
        work = [(root_q, 0, res_root)]
        while work:
            q, idx, out = work[-1]
            if idx >= len(q):
                memo[id(q)] = out
                work.pop()
                continue
            work[-1] = (q, idx + 1, out)
            op, tok_idx, arg = q[idx]
            if op == 1:
                sub_out = []
                out.append(sub_out)
                if id(arg) in memo:
                    sub_out.extend(memo[id(arg)])
                else:
                    work.append((arg, 0, sub_out))
            else:
                out.append(tokens[tok_idx])
        return res_root

    result = [v if type(v) is int else format_quot(v) for v in val_stack]
    return ("ok", result)

def filter_records(query: str, records: list[dict]) -> tuple:
    # -------------------------------------------------------------------------
    # STEP 1: LEXING
    # -------------------------------------------------------------------------
    tokens = []
    i = 0
    n = len(query)

    # Precompute character sets for fast lookup
    letters_underscore = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_")
    word_chars = letters_underscore | set("0123456789.")
    digits = set("0123456789")
    whitespace = {' ', '\t', '\n'}
    punct = {'(', ')', '[', ']', ','}
    keywords = {'and', 'or', 'not', 'in', 'has'}

    while i < n:
        c = query[i]
        if c in whitespace:
            i += 1
            continue

        if c in punct:
            tokens.append((c, c, i, None))
            i += 1
            continue

        # Two-character comparison operators (tried first)
        if i + 1 < n:
            two = query[i:i+2]
            if two in ('!=', '<=', '>='):
                tokens.append(('CMP', two, i, two))
                i += 2
                continue

        # Single-character comparison operators
        if c in ('=', '<', '>'):
            tokens.append(('CMP', c, i, c))
            i += 1
            continue

        # INT: optional '-' immediately followed by ASCII digit(s)
        if c in digits or (c == '-' and i + 1 < n and query[i+1] in digits):
            start = i
            if c == '-':
                i += 1
            while i < n and query[i] in digits:
                i += 1
            raw = query[start:i]
            tokens.append(('INT', raw, start, int(raw)))
            continue

        # STRING
        if c == '"':
            start = i
            i += 1
            chars = []
            closed = False
            while i < n:
                ch = query[i]
                if ch == '"':
                    i += 1
                    closed = True
                    break
                elif ch == '\\':
                    if i + 1 >= n:
                        return ("error", i, "bad escape")
                    nxt = query[i+1]
                    if nxt in ('"', '\\'):
                        chars.append(nxt)
                        i += 2
                    else:
                        return ("error", i, "bad escape")
                else:
                    chars.append(ch)
                    i += 1
            if not closed:
                return ("error", start, "unterminated string")
            raw = query[start:i]
            tokens.append(('STRING', raw, start, "".join(chars)))
            continue

        # WORD (Keywords or FIELD)
        if c in letters_underscore:
            start = i
            i += 1
            while i < n and query[i] in word_chars:
                i += 1
            raw = query[start:i]
            if raw in keywords:
                tokens.append((raw, raw, start, raw))
            else:
                tokens.append(('FIELD', raw, start, raw))
            continue

        # Any other character is an error
        return ("error", i, f"unexpected character '{c}'")

    tokens.append(('END', '', n, None))

    # -------------------------------------------------------------------------
    # STEP 2: PARSING (Iterative State Machine + Shunting-Yard to RPN)
    # -------------------------------------------------------------------------
    idx = 0
    rpn = []
    op_stack = []
    prec = {'(': 0, 'or': 1, 'and': 2, 'not': 3}

    # Parser states: 0 represents expecting a `not_expr` (start of expression or
    # after an operator/open paren), 1 represents expecting binary operators,
    # closing parens, or END (after a complete `primary` expression).
    state = 0

    def syntax_error(tok):
        if tok[0] == 'END':
            return ("error", tok[2], "unexpected end of input")
        return ("error", tok[2], f"unexpected token '{tok[1]}'")

    while True:
        tok = tokens[idx]
        ttype = tok[0]

        if state == 0:
            if ttype == 'not':
                op_stack.append('not')
                idx += 1
            elif ttype == '(':
                op_stack.append('(')
                idx += 1
            elif ttype == 'has':
                idx += 1
                if tokens[idx][0] != 'FIELD':
                    return syntax_error(tokens[idx])
                field_name = tokens[idx][3]
                idx += 1
                rpn.append((0, field_name))  # 0: HAS
                state = 1
            elif ttype == 'FIELD':
                field_name = tok[3]
                idx += 1
                op_tok = tokens[idx]
                if op_tok[0] == 'CMP':
                    cmp_op = op_tok[3]
                    idx += 1
                    lit_tok = tokens[idx]
                    if lit_tok[0] not in ('INT', 'STRING'):
                        return syntax_error(lit_tok)
                    lit_val = lit_tok[3]
                    idx += 1
                    rpn.append((1, field_name, cmp_op, lit_val))  # 1: CMP
                    state = 1
                elif op_tok[0] == 'in':
                    idx += 1
                    if tokens[idx][0] != '[':
                        return syntax_error(tokens[idx])
                    idx += 1
                    lit_tok = tokens[idx]
                    if lit_tok[0] not in ('INT', 'STRING'):
                        return syntax_error(lit_tok)
                    lits = [lit_tok[3]]
                    idx += 1
                    while True:
                        sep_tok = tokens[idx]
                        if sep_tok[0] == ',':
                            idx += 1
                            lit_tok = tokens[idx]
                            if lit_tok[0] not in ('INT', 'STRING'):
                                return syntax_error(lit_tok)
                            lits.append(lit_tok[3])
                            idx += 1
                        elif sep_tok[0] == ']':
                            idx += 1
                            break
                        else:
                            return syntax_error(sep_tok)
                    rpn.append((2, field_name, set(lits)))  # 2: IN
                    state = 1
                else:
                    return syntax_error(op_tok)
            else:
                return syntax_error(tok)

        else:  # state == 1
            while op_stack and op_stack[-1] == 'not':
                op_stack.pop()
                rpn.append((3,))  # 3: NOT

            if ttype in ('and', 'or'):
                p = prec[ttype]
                while op_stack and prec[op_stack[-1]] >= p:
                    op = op_stack.pop()
                    rpn.append((4,) if op == 'and' else (5,))
                op_stack.append(ttype)
                idx += 1
                state = 0
            elif ttype == ')':
                while op_stack and op_stack[-1] != '(':
                    op = op_stack.pop()
                    rpn.append((4,) if op == 'and' else (5,))
                if not op_stack:
                    return syntax_error(tok)
                op_stack.pop()  # Pop matching '('
                idx += 1
                state = 1
            elif ttype == 'END':
                while op_stack and op_stack[-1] != '(':
                    op = op_stack.pop()
                    rpn.append((4,) if op == 'and' else (5,))
                if op_stack:
                    return syntax_error(tok)
                break
            else:
                return syntax_error(tok)

    # -------------------------------------------------------------------------
    # STEP 3: EVALUATION
    # -------------------------------------------------------------------------
    if not records:
        return ("ok", [])

    # Truth value encoding:
    # 0 = FALSE, 1 = UNKNOWN, 2 = TRUE
    not_table = (2, 1, 0)
    matching_indices = []

    for rec_idx, rec in enumerate(records):
        stack = []
        for instr in rpn:
            op = instr[0]
            if op == 1:  # CMP: (1, field, cmp_op, lit_val)
                field = instr[1]
                if field not in rec:
                    stack.append(1)
                else:
                    val = rec[field]
                    lit = instr[3]
                    cmp_op = instr[2]
                    if type(val) is not type(lit):
                        if cmp_op == '=':
                            stack.append(0)
                        elif cmp_op == '!=':
                            stack.append(2)
                        else:
                            stack.append(1)
                    else:
                        if cmp_op == '=':
                            res = (val == lit)
                        elif cmp_op == '!=':
                            res = (val != lit)
                        elif cmp_op == '<':
                            res = (val < lit)
                        elif cmp_op == '<=':
                            res = (val <= lit)
                        elif cmp_op == '>':
                            res = (val > lit)
                        else:  # '>='
                            res = (val >= lit)
                        stack.append(2 if res else 0)
            elif op == 0:  # HAS: (0, field)
                stack.append(2 if instr[1] in rec else 0)
            elif op == 2:  # IN: (2, field, set_of_lits)
                field = instr[1]
                if field not in rec:
                    stack.append(1)
                else:
                    # Since record values & literals are strictly int or str,
                    # Python's set lookup naturally enforces same-type equality.
                    stack.append(2 if rec[field] in instr[2] else 0)
            elif op == 3:  # NOT
                stack[-1] = not_table[stack[-1]]
            elif op == 4:  # AND (min of 0, 1, 2)
                b = stack.pop()
                a = stack[-1]
                if b < a:
                    stack[-1] = b
            elif op == 5:  # OR (max of 0, 1, 2)
                b = stack.pop()
                a = stack[-1]
                if b > a:
                    stack[-1] = b

        if stack[0] == 2:
            matching_indices.append(rec_idx)

    return ("ok", matching_indices)

import re

# Token types
T_INT = 0
T_NAME = 1
T_OP = 2
T_INV = 3
T_END = 4

# Master regex for fast tokenization
_TOKEN_RE = re.compile(
    r"( +)|([0-9]+)|([a-z_][a-z0-9_]*)|(<=|>=|==|!=|[+\-*/%^()?:<>])|([\s\S])"
)


def _tokenize(src: str):
    tokens = []
    append = tokens.append
    for m in _TOKEN_RE.finditer(src):
        g = m.lastindex
        if g == 1:
            continue
        elif g == 2:
            append((T_INT, m.group(2), m.start()))
        elif g == 3:
            append((T_NAME, m.group(3), m.start()))
        elif g == 4:
            append((T_OP, m.group(4), m.start()))
        else:
            append((T_INV, m.group(5), m.start()))
    append((T_END, "", len(src)))
    return tokens


def _syntax_error(tok):
    ttype, tval, tpos = tok
    if ttype == T_END:
        return ("error", tpos, "unexpected end of input")
    elif ttype == T_INV:
        return ("error", tpos, f"unexpected character '{tval}'")
    else:
        return ("error", tpos, f"unexpected token '{tval}'")


# AST Node types
N_INT = 0
N_NAME = 1
N_UNARY = 2
N_BIN = 3
N_COND = 4

# Parser state machine states
S_COND = 0
S_COND_AFTER_CMP = 1
S_COND_AFTER_TRUE = 2
S_COND_AFTER_FALSE = 3
S_CMP = 4
S_CMP_AFTER_FIRST = 5
S_CMP_AFTER_SECOND = 6
S_SUM = 7
S_SUM_LOOP = 8
S_SUM_COMBINE = 9
S_TERM = 10
S_TERM_LOOP = 11
S_TERM_COMBINE = 12
S_UNARY = 13
S_UNARY_COMBINE = 14
S_POWER = 15
S_POWER_AFTER_ATOM = 16
S_POWER_COMBINE = 17
S_ATOM = 18
S_ATOM_AFTER_COND = 19

_CMP_OPS = {"<", "<=", ">", ">=", "==", "!="}
_SUM_OPS = {"+", "-"}
_TERM_OPS = {"*", "/", "%"}


def evaluate(src: str, env: dict) -> tuple:
    tokens = _tokenize(src)
    idx = 0

    # --- 1. PARSING PHASE (Iterative Recursive-Descent) ---
    p_stack = [S_COND]
    v_stack = []
    push_p = p_stack.append
    pop_p = p_stack.pop
    push_v = v_stack.append
    pop_v = v_stack.pop

    while p_stack:
        state = pop_p()

        if state == S_ATOM:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_INT:
                idx += 1
                push_v((N_INT, int(tval)))
            elif ttype == T_NAME:
                idx += 1
                push_v((N_NAME, tval, tpos))
            elif ttype == T_OP and tval == "(":
                idx += 1
                push_p(S_ATOM_AFTER_COND)
                push_p(S_COND)
            else:
                return _syntax_error(tokens[idx])

        elif state == S_ATOM_AFTER_COND:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval == ")":
                idx += 1
            else:
                return _syntax_error(tokens[idx])

        elif state == S_POWER:
            push_p(S_POWER_AFTER_ATOM)
            push_p(S_ATOM)

        elif state == S_POWER_AFTER_ATOM:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval == "^":
                idx += 1
                push_v((tval, tpos))
                push_p(S_POWER_COMBINE)
                push_p(S_UNARY)

        elif state == S_POWER_COMBINE:
            right = pop_v()
            op, tpos = pop_v()
            left = pop_v()
            push_v((N_BIN, op, tpos, left, right))

        elif state == S_UNARY:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval == "-":
                idx += 1
                push_v(tpos)
                push_p(S_UNARY_COMBINE)
                push_p(S_UNARY)
            else:
                push_p(S_POWER)

        elif state == S_UNARY_COMBINE:
            operand = pop_v()
            tpos = pop_v()
            push_v((N_UNARY, tpos, operand))

        elif state == S_TERM:
            push_p(S_TERM_LOOP)
            push_p(S_UNARY)

        elif state == S_TERM_LOOP:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval in _TERM_OPS:
                idx += 1
                push_v((tval, tpos))
                push_p(S_TERM_LOOP)
                push_p(S_TERM_COMBINE)
                push_p(S_UNARY)

        elif state == S_TERM_COMBINE:
            right = pop_v()
            op, tpos = pop_v()
            left = pop_v()
            push_v((N_BIN, op, tpos, left, right))

        elif state == S_SUM:
            push_p(S_SUM_LOOP)
            push_p(S_TERM)

        elif state == S_SUM_LOOP:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval in _SUM_OPS:
                idx += 1
                push_v((tval, tpos))
                push_p(S_SUM_LOOP)
                push_p(S_SUM_COMBINE)
                push_p(S_TERM)

        elif state == S_SUM_COMBINE:
            right = pop_v()
            op, tpos = pop_v()
            left = pop_v()
            push_v((N_BIN, op, tpos, left, right))

        elif state == S_CMP:
            push_p(S_CMP_AFTER_FIRST)
            push_p(S_SUM)

        elif state == S_CMP_AFTER_FIRST:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval in _CMP_OPS:
                idx += 1
                push_v((tval, tpos))
                push_p(S_CMP_AFTER_SECOND)
                push_p(S_SUM)

        elif state == S_CMP_AFTER_SECOND:
            right = pop_v()
            op, tpos = pop_v()
            left = pop_v()
            push_v((N_BIN, op, tpos, left, right))

        elif state == S_COND:
            push_p(S_COND_AFTER_CMP)
            push_p(S_CMP)

        elif state == S_COND_AFTER_CMP:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval == "?":
                idx += 1
                push_p(S_COND_AFTER_TRUE)
                push_p(S_COND)

        elif state == S_COND_AFTER_TRUE:
            ttype, tval, tpos = tokens[idx]
            if ttype == T_OP and tval == ":":
                idx += 1
                push_p(S_COND_AFTER_FALSE)
                push_p(S_COND)
            else:
                return _syntax_error(tokens[idx])

        elif state == S_COND_AFTER_FALSE:
            false_branch = pop_v()
            true_branch = pop_v()
            cond_expr = pop_v()
            push_v((N_COND, cond_expr, true_branch, false_branch))

    # Must be at END token after parsing a full cond
    if tokens[idx][0] != T_END:
        return _syntax_error(tokens[idx])

    ast = v_stack[0]

    # --- 2. EVALUATION PHASE (Iterative AST Walker) ---
    E_EVAL = 0
    E_UNARY = 1
    E_BIN_RIGHT = 2
    E_BIN_APPLY = 3
    E_COND_BRANCH = 4

    e_stack = [(E_EVAL, ast)]
    r_stack = []
    push_e = e_stack.append
    pop_e = e_stack.pop
    push_r = r_stack.append
    pop_r = r_stack.pop

    while e_stack:
        action, data = pop_e()

        if action == E_EVAL:
            ntype = data[0]
            if ntype == N_INT:
                push_r(data[1])
            elif ntype == N_NAME:
                name = data[1]
                if name in env:
                    push_r(env[name])
                else:
                    return ("error", data[2], f"unknown name '{name}'")
            elif ntype == N_UNARY:
                push_e((E_UNARY, None))
                push_e((E_EVAL, data[2]))
            elif ntype == N_BIN:
                push_e((E_BIN_RIGHT, data))
                push_e((E_EVAL, data[3]))
            elif ntype == N_COND:
                push_e((E_COND_BRANCH, data))
                push_e((E_EVAL, data[1]))

        elif action == E_UNARY:
            push_r(-pop_r())

        elif action == E_BIN_RIGHT:
            push_e((E_BIN_APPLY, data))
            push_e((E_EVAL, data[4]))

        elif action == E_BIN_APPLY:
            right = pop_r()
            left = pop_r()
            op = data[1]
            pos = data[2]

            if op == "+":
                push_r(left + right)
            elif op == "-":
                push_r(left - right)
            elif op == "*":
                push_r(left * right)
            elif op == "/":
                if right == 0:
                    return ("error", pos, "division by zero")
                push_r(left // right)
            elif op == "%":
                if right == 0:
                    return ("error", pos, "division by zero")
                push_r(left % right)
            elif op == "^":
                if right < 0:
                    return ("error", pos, "negative exponent")
                if right > 256:
                    return ("error", pos, "exponent too large")
                push_r(left**right)
            elif op == "<":
                push_r(1 if left < right else 0)
            elif op == "<=":
                push_r(1 if left <= right else 0)
            elif op == ">":
                push_r(1 if left > right else 0)
            elif op == ">=":
                push_r(1 if left >= right else 0)
            elif op == "==":
                push_r(1 if left == right else 0)
            elif op == "!=":
                push_r(1 if left != right else 0)

        elif action == E_COND_BRANCH:
            cond_val = pop_r()
            if cond_val != 0:
                push_e((E_EVAL, data[2]))
            else:
                push_e((E_EVAL, data[3]))

    return ("ok", r_stack[0])

from collections import OrderedDict
import heapq
from itertools import count


def run_cache(capacity, ops):
    if isinstance(capacity, bool) or not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be a positive int")

    store = OrderedDict()  # key -> entry ([value, expires_at]); oldest use first
    expiry_heap = []       # min-heap of (expires_at, seq, key, entry)
    seq = count()
    out = []
    last_t = None

    def purge_expired(t):
        while expiry_heap and expiry_heap[0][0] <= t:
            _, _, k, entry = heapq.heappop(expiry_heap)
            if store.get(k) is entry:
                del store[k]

    for op in ops:
        kind, t = op[0], op[1]
        if last_t is not None and t < last_t:
            raise ValueError("operations must have non-decreasing timestamps")
        last_t = t

        if kind == "put":
            _, _, key, value, ttl = op
            if ttl is not None and (
                isinstance(ttl, bool) or not isinstance(ttl, int) or ttl < 1
            ):
                raise ValueError("ttl must be None or a positive int")

            purge_expired(t)
            expires_at = None if ttl is None else t + ttl

            if key in store:
                del store[key]
            elif len(store) >= capacity:
                store.popitem(last=False)

            entry = [value, expires_at]
            store[key] = entry
            if expires_at is not None:
                heapq.heappush(expiry_heap, (expires_at, next(seq), key, entry))

        elif kind == "get":
            key = op[2]
            purge_expired(t)
            entry = store.get(key)
            if entry is None:
                out.append(None)
            else:
                store.move_to_end(key)
                out.append(entry[0])

        elif kind == "size":
            purge_expired(t)
            out.append(len(store))

        else:
            raise ValueError("unknown operation %r" % (kind,))

    return out

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live (not yet deleted) element counts
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap and delayed[sign * heap[0]]:
            delayed[sign * heap[0]] -= 1
            heapq.heappop(heap)

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)

    def add(x):
        if not low or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        delayed[x] += 1
        if x <= -low[0]:
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        out.append(-low[0] if sizes["low"] else None)
    return out

TWO_CHAR_OPS = ("==", "!=", "<=", ">=", "->")
ONE_CHAR_OPS = "<>=+-*/(),"
ESCAPES = {'"': '"', "\\": "\\", "n": "\n", "t": "\t"}


def _is_digit(ch):
    return "0" <= ch <= "9"


def _is_ident_start(ch):
    return ch == "_" or "a" <= ch <= "z" or "A" <= ch <= "Z"


def _is_ident_char(ch):
    return _is_ident_start(ch) or _is_digit(ch)


def tokenize(src):
    tokens = []
    n = len(src)
    i, line, col = 0, 1, 1

    def fail(at_line, at_col, message):
        raise ValueError("line %d col %d: %s" % (at_line, at_col, message))

    while i < n:
        ch = src[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch == " " or ch == "\t":
            i += 1
            col += 1
            continue
        if ch == "#":
            end = src.find("\n", i)
            if end == -1:
                i = n
            else:
                col += end - i
                i = end
            continue

        if _is_digit(ch):
            j = i
            while j < n and _is_digit(src[j]):
                j += 1
            is_float = False
            if j + 1 < n and src[j] == "." and _is_digit(src[j + 1]):
                j += 1
                while j < n and _is_digit(src[j]):
                    j += 1
                is_float = True
            if j < n and src[j] in "eE":
                k = j + 1
                if k < n and src[k] in "+-":
                    k += 1
                if k < n and _is_digit(src[k]):
                    j = k
                    while j < n and _is_digit(src[j]):
                        j += 1
                    is_float = True
            text = src[i:j]
            tokens.append(("NUMBER", float(text) if is_float else int(text), line, col))
            col += j - i
            i = j
            continue

        if _is_ident_start(ch):
            j = i
            while j < n and _is_ident_char(src[j]):
                j += 1
            tokens.append(("IDENT", src[i:j], line, col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            chars = []
            while True:
                if j >= n or src[j] == "\n":
                    fail(line, col, "unterminated string")
                c = src[j]
                if c == '"':
                    j += 1
                    break
                if c == "\\":
                    if j + 1 >= n or src[j + 1] == "\n":
                        fail(line, col, "unterminated string")
                    if src[j + 1] not in ESCAPES:
                        fail(line, col + (j - i), "bad escape")
                    chars.append(ESCAPES[src[j + 1]])
                    j += 2
                    continue
                chars.append(c)
                j += 1
            tokens.append(("STRING", "".join(chars), line, col))
            col += j - i
            i = j
            continue

        if src[i:i + 2] in TWO_CHAR_OPS:
            tokens.append(("OP", src[i:i + 2], line, col))
            i += 2
            col += 2
            continue
        if ch in ONE_CHAR_OPS:
            tokens.append(("OP", ch, line, col))
            i += 1
            col += 1
            continue

        fail(line, col, "unexpected character %r" % ch)

    return tokens
